def _t_eval(target, _t, scope):
    t_path = _t.__ops__
    root = t_path[0]

    if root is S:
        cur = _s_first_magic(scope, scope[T], _t)
    else:
        cur = target

    i = 1
    while i < len(t_path):
        op, arg = t_path[i], t_path[i + 1]
        i += 2

        if op == '.':
            try:
                cur = getattr(cur, arg)
            except AttributeError as e:
                raise PathAccessError(e, Path(_t), (i - 2) // 2)
        elif op == '[':
            try:
                cur = cur[arg]
            except (KeyError, IndexError, TypeError) as e:
                raise PathAccessError(e, Path(_t), (i - 2) // 2)
        elif op == 'P':
            _get = scope[TargetRegistry].get_handler('get', cur, path=scope[Path])
            try:
                cur = _get(cur, arg)
            except Exception as e:
                raise PathAccessError(e, Path(_t), (i - 2) // 2)
        elif op == '(':
            args, kwargs = arg
            args = arg_val(target, args, scope)
            kwargs = arg_val(target, kwargs, scope)
            try:
                cur = cur(*args, **kwargs)
            except Exception as e:
                raise PathAccessError(e, Path(_t), (i - 2) // 2)
        elif op == 'x':
            _iterate = scope[TargetRegistry].get_handler('iterate', cur, path=scope[Path])
            try:
                cur = list(_iterate(cur))
            except Exception as e:
                raise PathAccessError(e, Path(_t), (i - 2) // 2)
        elif op == 'X':
            def _recursive_iter(obj):
                yield obj
                _get_handler = scope[TargetRegistry].get_handler
                try:
                    children = []
                    _extend_children(children, obj, _get_handler)
                    for child in children:
                        for item in _recursive_iter(child):
                            yield item
                except Exception:
                    pass
            cur = list(_recursive_iter(cur))
        elif op in ('+', '-', '*', '#', '/', '%', ':', '&', '|', '^'):
            arg_val_result = arg_val(target, arg, scope)
            try:
                if op == '+':
                    cur = cur + arg_val_result
                elif op == '-':
                    cur = cur - arg_val_result
                elif op == '*':
                    cur = cur * arg_val_result
                elif op == '#':
                    cur = cur // arg_val_result
                elif op == '/':
                    cur = cur / arg_val_result
                elif op == '%':
                    cur = cur % arg_val_result
                elif op == ':':
                    cur = cur ** arg_val_result
                elif op == '&':
                    cur = cur & arg_val_result
                elif op == '|':
                    cur = cur | arg_val_result
                elif op == '^':
                    cur = cur ^ arg_val_result
            except Exception as e:
                raise PathAccessError(e, Path(_t), (i - 2) // 2)
        elif op == '~':
            try:
                cur = ~cur
            except Exception as e:
                raise PathAccessError(e, Path(_t), (i - 2) // 2)
        elif op == '_':
            try:
                cur = -cur
            except Exception as e:
                raise PathAccessError(e, Path(_t), (i - 2) // 2)

    return cur


def _handle_list(target, spec, scope):
    ret = []
    for item in target:
        child_scope = chain_child(scope)
        val = child_scope[glom](item, spec[0] if spec else T, child_scope)
        if val is SKIP:
            continue
        if val is STOP:
            break
        ret.append(val)
        child_scope[Path] += [getattr(spec[0], '__name__', spec[0])] if spec else []
    return ret


def glom(target, spec, **kwargs):
    scope = kwargs.pop('scope', None)
    if scope is None:
        scope = _DEFAULT_SCOPE
    elif not isinstance(scope, ChainMap):
        scope = ChainMap(scope)

    default = kwargs.pop('default', _MISSING)
    skip_exc = kwargs.pop('skip_exc', GlomError)
    glom_debug = kwargs.pop('glom_debug', GLOM_DEBUG)

    if kwargs:
        raise TypeError(f'unexpected keyword arguments: {sorted(kwargs.keys())!r}')

    scope = scope.new_child({
        Path: [],
        MODE: AUTO,
        MIN_MODE: None,
    })

    try:
        return _glom(target, spec, scope)
    except skip_exc as e:
        if default is not _MISSING:
            return arg_val(target, default, scope)
        if glom_debug:
            raise
        if isinstance(e, GlomError):
            e._finalize(scope)
        raise
